using GBA;

public class PlayerLogic : Behaviour
{
    PlatformerBody body;

    void Start() => body = Get<PlatformerBody>();

    void Update()
    {
        if (Input.Pressed(Key.A) && body.OnGround)
        {
            body.vy = -3.50;
            Sound.Play("jump", 0.8);
        }
    }

    void OnTouch(Actor other)
    {
        if (other.tag == "Coin")
        {
            Game.score += 10;
            other.Destroy();
        }
    }
}
